    [Test]
    public void Multiply_MatchesArmSimulation()
    {
        foreach (var (a, b, expected) in Cases)
        {
            int actual = FixedPoint.Multiply(a, b);
            Assert.That(actual, Is.EqualTo(expected),
                $"Multiply(0x{a:X8}, 0x{b:X8}) = 0x{actual:X8}, expected 0x{expected:X8}");
        }
    }
